public class Driver {static <N extends Number>double average(N[] n){double s=0;for(N x:n)s+=x.doubleValue();return n.length==0?0:s/n.length;}public static void main(String[]a){System.out.printf("Integer Average: %.2f%n",average(new Integer[]{10,20,30,40}));System.out.printf("Double Average: %.2f%n",average(new Double[]{1.5,2.5,3.5}));System.out.printf("Long Average: %.2f%n",average(new Long[]{100L,200L,300L}));}}
